CREATE VIEW [FO].[vwLedgerJournalTrans]
AS
SELECT T1.VOUCHER AS VOUCHER
	,T1.LEDGERVOUCHERTYPE_CN AS CHINESEVOUCHERTYPERECID
	,T1.VOUCHER_CN AS CHINESEVOUCHER
	,T1.LINENUM AS LINENUMBER
	,T1.INVOICE AS INVOICEID
	,T1.COMPANY AS COMPANY
	,T1.ACCOUNTTYPE AS ACCOUNTTYPE
	,T1.TRANSDATE AS INVOICEDATE
	,T1.LEDGERDIMENSION AS CUSTOMERACCOUNT
	,T1.AMOUNTCURCREDIT AS CREDITAMOUNT
	,T1.AMOUNTCURDEBIT AS DEBITAMOUNT
	,T1.CURRENCYCODE AS CURRENCY
	,T1.TXT AS TRANSACTIONTEXT
	,T1.CASHDISCCODE AS CASHDISCOUNTCODE
	,T1.CASHDISCAMOUNT AS CASHDISCOUNTAMOUNT
	,T1.DATECASHDISC AS CASHDISCOUNTDATE
	,T1.DOCUMENTDATE AS DOCUMENTDATE
	,T1.DOCUMENTNUM AS DOCUMENTNUMBER
	,T1.DUE AS DUEDATE
	,T1.LEDGERJOURNALDLVDATE_ES AS DELIVERYDATE
	,T1.LISTCODE AS LISTCODE
	,T1.OFFSETACCOUNTTYPE AS OFFSETACCOUNTTYPE
	,T1.OFFSETCOMPANY AS OFFSETCOMPANY
	,T1.OFFSETLEDGERDIMENSION AS OFFSETACCOUNT
	,T1.OFFSETTXT AS OFFSETTRANSACTIONTEXT
	,T1.PAYMENT AS TERMSOFPAYMENT
	,T1.PAYMMODE AS METHODOFPAYMENT
	,T1.OPERATIONTYPE_MX AS TYPEOFOPERATION
	,T1.PAYMSPEC AS PAYMENTSPECIFICATION
	,T1.POSTINGPROFILE AS POSTINGPROFILE
	,T1.TAXGROUP AS SALESTAXGROUP
	,T1.TAXITEMGROUP AS ITEMSALESTAXGROUP
	,T1.VATNUMJOURNAL AS TAXEXEMPTNUMBER
	,T1.APPROVED AS APPROVED
	,T1.APPROVER AS APPROVERRECID
	,T1.TRANSACTIONTYPE AS TRANSACTIONTYPE
	,T1.REASONREFRECID AS REASONREFRECID
	,T1.TAXWITHHOLDCALCULATE_TH AS ISWITHHOLDINGCALCULATIONENABLED
	,T1.DEFAULTDIMENSION AS DEFAULTDIMENSION
	,T1.BANKTRANSTYPE AS BANKTRANSACTIONTYPE
	,T1.CUSTVENDBANKACCOUNTID AS CUSTVENDBANKACCOUNTID
	,T1.EXCHRATE AS EXCHRATE
	,T1.REPORTINGCURRENCYEXCHRATE AS REPORTINGCURRENCYEXCHRATE
	,T1.PRICE AS PRICE
	,T1.QTY AS QTY
	,T1.LINENUM AS LINENUM
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.RECVERSION AS RECVERSION
	,T1.DATAAREAID AS DATAAREAID
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID
	,T2.PERSONNELNUMBER AS APPROVEDBY
	,T2.RECVERSION AS RECVERSION#2
	,T2.PARTITION AS PARTITION#2
	,T2.RECID AS RECID#2
	,T3.DISPLAYVALUE AS CUSTOMERACCOUNTDISPLAYVALUE
	,T3.RECVERSION AS RECVERSION#3
	,T3.PARTITION AS PARTITION#3
	,T3.RECID AS RECID#3
	,T4.DISPLAYVALUE AS OFFSETACCOUNTDISPLAYVALUE
	,T4.RECVERSION AS RECVERSION#4
	,T4.PARTITION AS PARTITION#4
	,T4.RECID AS RECID#4
	,T5.JOURNALNUM AS JOURNALBATCHNUMBER
	,T5.EXCHRATESECONDARY AS EXCHRATESECONDARY
	,T5.NAME AS NAME
	,T5.RECVERSION AS RECVERSION#5
	,T5.DATAAREAID AS DATAAREAID#5
	,T5.PARTITION AS PARTITION#5
	,T5.RECID AS RECID#5
	,T6.REASON AS REASONCODE
	,T6.REASONCOMMENT AS REASONCOMMENT
	,T6.RECVERSION AS RECVERSION#6
	,T6.DATAAREAID AS DATAAREAID#6
	,T6.PARTITION AS PARTITION#6
	,T6.RECID AS RECID#6
	,T7.TAXWITHHOLDITEMGROUP AS ITEMWITHHOLDINGTAXGROUPCODE
	,T7.RECVERSION AS RECVERSION#7
	,T7.DATAAREAID AS DATAAREAID#7
	,T7.PARTITION AS PARTITION#7
	,T7.RECID AS RECID#7
	,T8.ID AS CHINESEVOUCHERTYPE
	,T8.RECVERSION AS RECVERSION#8
	,T8.DATAAREAID AS DATAAREAID#8
	,T8.PARTITION AS PARTITION#8
	,T8.RECID AS RECID#8
	,T9.DISPLAYVALUE AS DEFAULTDIMENSIONDISPLAYVALUE
	,T9.RECVERSION AS RECVERSION#9
	,T9.PARTITION AS PARTITION#9
	,T9.RECID AS RECID#9
FROM [synapse_fo].[LEDGERJOURNALTRANS] T1
LEFT OUTER JOIN [synapse_fo].[HCMWORKER] T2 ON (
		(T1.APPROVER = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T3 ON (
		(T1.LEDGERDIMENSION = T3.RECID)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONCOMBINATIONENTITY_RICS] T4 ON (
		(T1.OFFSETLEDGERDIMENSION = T4.RECID)
		AND (T1.PARTITION = T4.PARTITION)
		)
CROSS JOIN [synapse_fo].[LEDGERJOURNALTABLE] T5
LEFT OUTER JOIN [synapse_fo].[REASONTABLEREF] T6 ON (
		(
			(T1.REASONREFRECID = T6.RECID)
			AND (T1.DATAAREAID = T6.DATAAREAID)
			)
		AND (T1.PARTITION = T6.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[TAXWITHHOLDITEMGROUPHEADING_TH] T7 ON (
		(
			(T1.TAXWITHHOLDITEMGROUPHEADING_TH = T7.RECID)
			AND (T1.DATAAREAID = T7.DATAAREAID)
			)
		AND (T1.PARTITION = T7.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[LEDGERVOUCHERTYPE_CN] T8 ON (
		(
			(T1.LEDGERVOUCHERTYPE_CN = T8.RECID)
			AND (T1.DATAAREAID = T8.DATAAREAID)
			)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T9 ON (
		(T1.DEFAULTDIMENSION = T9.RECID)
		AND (T1.PARTITION = T9.PARTITION)
		)
WHERE (
		(
			(
				(
					(T1.ACCOUNTTYPE = 1)
					AND NOT ((T1.INVOICE = N'""'))
					)
				AND NOT ((T1.OFFSETLEDGERDIMENSION = 0))
				)
			AND (T1.OFFSETACCOUNTTYPE = 0)
			)
		AND (
			(T5.JOURNALTYPE = 0)
			AND (
				(
					(T1.JOURNALNUM = T5.JOURNALNUM)
					AND (T1.DATAAREAID = T5.DATAAREAID)
					)
				AND (T1.PARTITION = T5.PARTITION)
				)
			)
		)
